import { CubieCube } from "./CubeLib";
import { rand_choice } from "./Math";
import { EO_CASES, buildEOLRbCube, caseFromConstructed, type EOCaseId, type EOLRbCase } from "./EOLRbGenerator";
import { loadSelection } from "./Selection";

// The BLD trainer drills finer cases than the sighted EOLRb trainer: blind,
// where an LR edge sits relative to the top-layer corners' colors matters,
// not just which slot it's in. Each BLD subcase refines one of the sighted
// trainer's subcases ("parent") with an extra condition on the built cube;
// cases are generated by building the parent and rejecting until it holds.
//
// EO cases without a refinement yet reuse the sighted subcases 1:1 (same
// ids, so their existing stats keys are unchanged).

// Edge slots [UF, UL, UB, UR, DF, DB] and corner slots, per Defs.tsx:
// corners_coord = [UFL, ULB, UBR, URF, ...].
const UF = 0, UL = 1, UB = 2, UR = 3;
const TOP_SLOTS = [UF, UL, UB, UR];
const UFL = 0, ULB = 1, UBR = 2, URF = 3;

// The two top corners flanking each top edge slot.
const CORNERS_AROUND: Record<number, [number, number]> = {
    [UF]: [UFL, URF],
    [UL]: [UFL, ULB],
    [UB]: [ULB, UBR],
    [UR]: [UBR, URF],
};
// Corner pieces carrying the L-side color (the other two carry R's).
const L_COLORED_CORNERS = new Set([UFL, ULB]);
// LR edge pieces: the UL piece carries L's color, the UR piece R's.
const LR_PIECES = new Set([UL, UR]);

// How a top-layer LR edge sits relative to the two corners either side of it:
//  matching -- both corners share the edge's L/R color
//  opposite -- both corners have the other side's color
//  adjacent -- one of each
export type CornerRelation = "matching" | "opposite" | "adjacent";

export function edgeCornerRelation(cube: CubieCube, slot: number): CornerRelation {
    const edgeIsL = cube.ep[slot] === UL;
    const [a, b] = CORNERS_AROUND[slot].map((c) => L_COLORED_CORNERS.has(cube.cp[c]));
    if (a !== b) return "adjacent";
    return a === edgeIsL ? "matching" : "opposite";
}

// Corner relations of whichever LR edges are in the top layer (0-2 entries).
export function topLRRelations(cube: CubieCube): CornerRelation[] {
    return TOP_SLOTS.filter((s) => LR_PIECES.has(cube.ep[s])).map((s) => edgeCornerRelation(cube, s));
}

export type BLDSubcaseDef = {
    id: string;
    parent: string; // sighted subcase id it refines
    group?: string; // heading the chip is listed under; absent = ungrouped
    label: string; // short chip label
    fullLabel: string; // shown as the case name while training
    accept: (cube: CubieCube) => boolean;
};

export type BLDCaseDef = { id: EOCaseId; label: string; subcases: BLDSubcaseDef[] };

const always = () => true;

function refined(
    parent: string,
    group: string,
    variants: { rel: CornerRelation; label: string; fullLabel: string; accept: (rels: CornerRelation[]) => boolean }[]
): BLDSubcaseDef[] {
    return variants.map((v) => ({
        id: `${parent}::${v.rel}`,
        parent,
        group,
        label: v.label,
        fullLabel: `${group} · ${v.fullLabel}`,
        accept: (cube) => v.accept(topLRRelations(cube)),
    }));
}

const REL_WORD: Record<CornerRelation, string> = { opposite: "opposite", matching: "matching", adjacent: "adjacent" };
const THREE_RELS = ["opposite", "matching", "adjacent"] as const;

// Top slots holding an LR edge with the given orientation (eo is per slot:
// 1 = misoriented).
function topLRSlots(cube: CubieCube, misoriented: boolean): number[] {
    return TOP_SLOTS.filter((s) => LR_PIECES.has(cube.ep[s]) && (cube.eo[s] === 1) === misoriented);
}

// Building blocks, one per placement shape of the LR edges:

const unsplit = (id: string, label: string): BLDSubcaseDef => ({ id, parent: id, label, fullLabel: label, accept: always });

// 1 LR edge on top: its relation, any of the three.
const oneTop = (parent: string, group: string, edge = "top edge") =>
    refined(
        parent,
        group,
        THREE_RELS.map((rel) => ({
            rel,
            label: `Between ${REL_WORD[rel]}`,
            fullLabel: `${edge} between ${REL_WORD[rel]} colored corners`,
            accept: (rels) => rels.length === 1 && rels[0] === rel,
        }))
    );

// 2 LR edges on top, opposite each other: both edges always share a relation
// (both between same-colored corners -- matching, or both swapped/opposite --
// or both between mixed corners), so the three options cover it.
const twoTopOpposite = (parent: string, group: string, edges = "edges") =>
    refined(
        parent,
        group,
        THREE_RELS.map((rel) => ({
            rel,
            label: `Between ${REL_WORD[rel]}`,
            fullLabel: `${edges} between ${REL_WORD[rel]} colored corners`,
            accept: (rels) => rels.length === 2 && rels.every((r) => r === rel),
        }))
    );

// 2 LR edges on top, adjacent: one edge is always between mixed corners; the
// other is between matching or opposite ones, which tells the cases apart.
const twoTopAdjacent = (parent: string, group: string, edge = "edge") =>
    refined(
        parent,
        group,
        (["opposite", "matching"] as const).map((rel) => ({
            rel,
            label: `One between ${REL_WORD[rel]}`,
            fullLabel: `one ${edge} between ${REL_WORD[rel]} colored corners`,
            accept: (rels) => rels.length === 2 && rels.includes(rel),
        }))
    );

// 2 LR edges on top, one oriented and one misoriented: the relation of the
// named one (all three are possible whether the pair is adjacent or
// opposite).
const twoTopMixed = (parent: string, group: string, by: "oriented" | "misoriented"): BLDSubcaseDef[] =>
    (["matching", "opposite", "adjacent"] as const).map((rel) => ({
        id: `${parent}::${rel}`,
        parent,
        group,
        label: `${by === "oriented" ? "Oriented" : "Misoriented"} between ${REL_WORD[rel]}`,
        fullLabel: `${group} · ${by} LR edge between ${REL_WORD[rel]} colored corners`,
        accept: (cube: CubieCube) => {
            const [slot] = topLRSlots(cube, by === "misoriented");
            return slot !== undefined && edgeCornerRelation(cube, slot) === rel;
        },
    }));

// 4/0 and 0/2 (same shape).
const FOUR_ZERO_SUBCASES: BLDSubcaseDef[] = [
    unsplit("both-bottom", "2 on bottom"),
    ...oneTop("one-top-one-bottom", "1 on bottom, 1 on top"),
    ...twoTopOpposite("top-opposite", "2 on top (opposite)"),
    ...twoTopAdjacent("top-adjacent", "2 on top (adjacent)"),
];

// 2o/0: misoriented UF/UB, oriented UL/UR -- same-orientation top pairs are
// opposite pairs, the mixed pair is always adjacent.
const TWO_O_ZERO_SUBCASES: BLDSubcaseDef[] = [
    unsplit("both-bottom", "2 on bottom"),
    ...oneTop("bottom-top-misoriented", "1 on bottom, 1 on top (misoriented)", "top LR edge"),
    ...oneTop("bottom-top-oriented", "1 on bottom, 1 on top (oriented)", "top LR edge"),
    ...twoTopOpposite("top-both-misoriented", "2 on top (both misoriented)", "top edges"),
    ...twoTopOpposite("top-both-oriented", "2 on top (both oriented)", "top edges"),
    ...twoTopMixed("top-mixed", "2 on top (1 oriented, 1 misoriented)", "oriented"),
];

// 2a/0: misoriented UF/UR, oriented UL/UB -- same-orientation top pairs are
// adjacent pairs, and a mixed pair can be opposite or adjacent (two sighted
// subcases, each split by the misoriented edge's relation).
const TWO_A_ZERO_SUBCASES: BLDSubcaseDef[] = [
    unsplit("both-bottom", "2 on bottom"),
    ...oneTop("bottom-top-misoriented", "1 on bottom, 1 on top (misoriented)", "top LR edge"),
    ...oneTop("bottom-top-oriented", "1 on bottom, 1 on top (oriented)", "top LR edge"),
    ...twoTopAdjacent("top-both-misoriented", "2 on top (both misoriented)", "LR edge"),
    ...twoTopAdjacent("top-both-oriented", "2 on top (both oriented)", "LR edge"),
    ...twoTopMixed("top-mixed-opposite", "2 on top (1 oriented, 1 misoriented, opposite)", "misoriented"),
    ...twoTopMixed("top-mixed-adjacent", "2 on top (1 oriented, 1 misoriented, adjacent)", "misoriented"),
];

const REFINEMENTS: Partial<Record<EOCaseId, BLDSubcaseDef[]>> = {
    "4/0": FOUR_ZERO_SUBCASES,
    "0/2": FOUR_ZERO_SUBCASES,
    "2o/0": TWO_O_ZERO_SUBCASES,
    "2a/0": TWO_A_ZERO_SUBCASES,
};

export const BLD_CASES: BLDCaseDef[] = EO_CASES.map((c) => ({
    id: c.id,
    label: c.label,
    subcases:
        REFINEMENTS[c.id] ??
        c.subcases.map((s) => ({ id: s.id, parent: s.id, label: s.label, fullLabel: s.label, accept: always })),
}));

const BLD_CASE_BY_ID = new Map(BLD_CASES.map((c) => [c.id, c]));

// The sighted subcases ("parents") of an EO case, each with the BLD subcases
// refining it -- the middle level of the case picker. An unrefined parent
// has exactly one BLD subcase: itself.
export type BLDParentGroup = { parent: string; label: string; subcases: BLDSubcaseDef[] };

export function bldParents(c: BLDCaseDef): BLDParentGroup[] {
    const out: BLDParentGroup[] = [];
    for (const s of c.subcases) {
        const last = out[out.length - 1];
        if (last && last.parent === s.parent) last.subcases.push(s);
        else out.push({ parent: s.parent, label: s.group ?? s.label, subcases: [s] });
    }
    return out;
}

export type BLDCombo = { eoCase: EOCaseId; subcase: string };

export function bldKey(c: BLDCombo): string {
    return `${c.eoCase}::${c.subcase}`;
}

export const BLD_COMBOS: BLDCombo[] = BLD_CASES.flatMap((c) => c.subcases.map((s) => ({ eoCase: c.id, subcase: s.id })));
export const BLD_KEYS = BLD_COMBOS.map(bldKey);
const BLD_KEY_SET = new Set(BLD_KEYS);

export function bldSubcase(eoCase: EOCaseId, subcase: string): BLDSubcaseDef | undefined {
    return BLD_CASE_BY_ID.get(eoCase)?.subcases.find((s) => s.id === subcase);
}

// e.g. "4/0 · 1 on bottom, 1 on top · top edge between matching colored corners".
export function bldCaseLabel(eoCase: EOCaseId, subcase: string): string {
    const sub = bldSubcase(eoCase, subcase);
    return sub ? `${BLD_CASE_BY_ID.get(eoCase)!.label} · ${sub.fullLabel}` : eoCase;
}

// Restores the saved selection. A saved key for a subcase that has since
// been split into finer BLD subcases enables all of its refinements, so an
// existing selection carries over.
export function restoreBLDEnabled(namespace: string): Set<string> {
    const saved = loadSelection(namespace);
    if (saved === null) return new Set(BLD_KEYS);
    const out = new Set<string>();
    for (const key of saved) {
        if (BLD_KEY_SET.has(key)) {
            out.add(key);
            continue;
        }
        const [eoCase, parent] = key.split("::");
        for (const s of BLD_CASE_BY_ID.get(eoCase as EOCaseId)?.subcases ?? []) {
            if (s.parent === parent) out.add(bldKey({ eoCase: eoCase as EOCaseId, subcase: s.id }));
        }
    }
    return out;
}

const MAX_TRIES = 500;

export function buildBLDCube(eoCase: EOCaseId, subcase: string): CubieCube {
    const sub = bldSubcase(eoCase, subcase)!;
    for (let i = 0; i < MAX_TRIES; i++) {
        const cube = buildEOLRbCube(eoCase, sub.parent);
        if (sub.accept(cube)) return cube;
    }
    throw new Error(`could not build BLD case ${eoCase}::${subcase}`);
}

export function generateBLDCase(combos: BLDCombo[]): EOLRbCase {
    const { eoCase, subcase } = rand_choice(combos.length > 0 ? combos : BLD_COMBOS);
    return caseFromConstructed(buildBLDCube(eoCase, subcase), eoCase, subcase);
}

export function bldCaseForEnabled(keys: Set<string>): EOLRbCase | null {
    const combos = BLD_COMBOS.filter((c) => keys.has(bldKey(c)));
    return combos.length > 0 ? generateBLDCase(combos) : null;
}
